INSERT INTO sys_config (code, sub_code, config, json_config, order_number, enabled, remarks, gmt_created, gmt_modified, gmt_deleted, is_deleted) VALUES ('height_eval', 'height_eval', null, '{"evaluation_rules": {"indicators": [{"grade": "上等 (超高)", "clinical_meaning": "身材高大。若远超同龄且父母身高普通，需排除骨龄提前、性早熟等异常风险。", "percentile_range": ">= P97"}, {"grade": "中上等 (偏高)", "clinical_meaning": "发育良好，在同龄人中属于偏高群体。", "percentile_range": "P75 <= 身高 < P97"}, {"grade": "中等 (正常中位数)", "clinical_meaning": "最常见的健康理想范围，P50为绝对平均线。", "percentile_range": "P25 <= 身高 < P75"}, {"grade": "中下等 (偏矮)", "clinical_meaning": "身材偏矮。建议持续监测年生长速度，排查是否有营养或运动不足。", "percentile_range": "P3 <= 身高 < P25"}, {"grade": "下等 (矮小)", "clinical_meaning": "达到儿童矮小症筛查标准，强烈建议前往小儿内分泌科或生长发育门诊就医排查。", "percentile_range": "< P3"}], "methodology": "百分位数法 (Percentile Method)", "rule_description": "将100个同年龄、同性别的正常儿童按身长/身高由矮到高排列，划分出5个等级区间用于评估个体的发育水平。", "dynamic_growth_warning": {"rule": "若连续两年每年身长/身高增长速度低于以下临界值，无论当前绝对高度处于何等级，均需警惕发育迟缓风险。", "criteria": {"0_to_1_year": "少于 25 cm/年", "1_to_3_years": "少于 8 cm/年", "3_years_to_pre_puberty": "少于 5 cm/年"}}}, "standard_metadata": {"unit": "厘米 (cm)", "measurement_rule": "0～2岁以下（即未满24个月）测量平卧位身长；2岁～7岁以下（24～84个月）测量站立位身高", "height_standard_version": ["中华人民共和国卫生行业标准《7岁以下儿童生长标准》(WS/T 423—2022)", "中华人民共和国卫生行业标准《学龄儿童青少年超重与肥胖筛查》(WS/T 586—2018)", "中国成人超重和肥胖症预防控制指南(WGOC)"]}, "height_percentile_data": {"male_boys": {"description": "7岁以下男童年龄别身长/身高百分位数值（源自标准文本表A.3）", "monthly_records": [{"P3": 47.6, "P10": 48.7, "P25": 49.9, "P50": 51.2, "P75": 52.5, "P90": 53.6, "P97": 54.8, "display": "0月(出生)", "age_months": 0}, {"P3": 51.3, "P10": 52.5, "P25": 53.8, "P50": 55.1, "P75": 56.5, "P90": 57.7, "P97": 59.0, "display": "1月", "age_months": 1}, {"P3": 54.9, "P10": 56.2, "P25": 57.5, "P50": 59.0, "P75": 60.4, "P90": 61.7, "P97": 63.0, "display": "2月", "age_months": 2}, {"P3": 58.0, "P10": 59.4, "P25": 60.7, "P50": 62.2, "P75": 63.7, "P90": 65.1, "P97": 66.4, "display": "3月", "age_months": 3}, {"P3": 60.5, "P10": 61.9, 