INSERT INTO sys_config (code, sub_code, config, json_config, order_number, enabled, remarks, gmt_created, gmt_modified, gmt_deleted, is_deleted) VALUES ('weight_eval', 'weight_eval', null, '{"evaluation_rules": {"indicators": [{"grade": "上等 (超重)", "clinical_meaning": "体重偏高。需警惕超重或肥胖风险，建议结合身高（BMI）综合评估，并注意饮食结构与运动。", "percentile_range": ">= P97"}, {"grade": "中上等 (偏重)", "clinical_meaning": "发育良好，营养充足。在同龄人中属于体重偏重群体。", "percentile_range": "P75 <= 体重 < P97"}, {"grade": "中等 (正常中位数)", "clinical_meaning": "最常见的健康理想范围，P50为绝对平均线。", "percentile_range": "P25 <= 体重 < P75"}, {"grade": "中下等 (偏轻)", "clinical_meaning": "体重偏轻。建议关注日常饮食摄入是否充足，排查是否有营养吸收不良等情况。", "percentile_range": "P3 <= 体重 < P25"}, {"grade": "下等 (低体重)", "clinical_meaning": "达到儿童低体重/营养不良筛查标准，建议前往儿童保健科或生长发育门诊就医排查原因。", "percentile_range": "< P3"}], "methodology": "百分位数法 (Percentile Method)", "rule_description": "将100个同年龄、同性别的正常儿童按体重由轻到重排列，划分出5个等级区间用于评估个体的发育水平。"}, "standard_metadata": {"unit": "千克 (kg)", "measurement_rule": "年龄为整月或整岁，体重单位为千克。", "standard_version": ["中华人民共和国卫生行业标准《7岁以下儿童生长标准》(WS/T 423—2022)"]}, "weight_percentile_data": {"male_boys": {"description": "7岁以下男童年龄别体重百分位数值（源自标准文本表A.1）", "monthly_records": [{"P3": 2.8, "P10": 3.0, "P25": 3.2, "P50": 3.5, "P75": 3.7, "P90": 4.0, "P97": 4.2, "display": "0月(出生)", "age_months": 0}, {"P3": 3.7, "P10": 3.9, "P25": 4.2, "P50": 4.6, "P75": 4.9, "P90": 5.2, "P97": 5.6, "display": "1月", "age_months": 1}, {"P3": 4.7, "P10": 5.0, "P25": 5.4, "P50": 5.8, "P75": 6.2, "P90": 6.7, "P97": 7.1, "display": "2月", "age_months": 2}, {"P3": 5.5, "P10": 5.9, "P25": 6.3, "P50": 6.8, "P75": 7.3, "P90": 7.8, "P97": 8.3, "display": "3月", "age_months": 3}, {"P3": 6.1, "P10": 6.5, "P25": 7.0, "P50": 7.5, "P75": 8.1, "P90": 8.6, "P97": 9.2, "display": "4月", "age_months": 4}, {"P3": 6.6, "P10": 7.0, "P25": 7.5, "P50": 8.0, "P75": 8.6, "P90": 9.2, "P97": 9.8, "display": "5月", "age_months": 5}, {"P3": 6.9, "P10": 7.4, "P25": 7.9, "P50": 8.4, "P75": 9.1, "P90": 9.7, "P97": 10.3, "display": "6月", "age_