INSERT INTO sys_config (code, sub_code, config, json_config, order_number, enabled, remarks, gmt_created, gmt_modified, gmt_deleted, is_deleted) VALUES ( 'head_circumference_eval', 'head_circumference_eval', null, '{"evaluation_rules": {"indicators": [{"grade": "上等 (头围偏大)", "clinical_meaning": "头围偏大。若增长过快或伴随前囟门饱满，需警惕脑积水、巨脑畸形等异常风险，建议咨询儿科医生。", "percentile_range": ">= P97"}, {"grade": "中上等 (偏大)", "clinical_meaning": "发育良好，头部略大于同龄人平均水平，通常属于正常生理差异。", "percentile_range": "P75 <= 头围 < P97"}, {"grade": "中等 (正常中位数)", "clinical_meaning": "最常见的健康理想范围，大脑发育处于绝对平均线附近。", "percentile_range": "P25 <= 头围 < P75"}, {"grade": "中下等 (偏小)", "clinical_meaning": "头围偏小。建议持续监测头围增长速度，排查是否有营养不良或生长发育迟缓。", "percentile_range": "P3 <= 头围 < P25"}, {"grade": "下等 (小头畸形风险)", "clinical_meaning": "达到小头畸形或严重发育迟缓的筛查标准，强烈建议前往儿童保健科或小儿神经内科就医排查原因。", "percentile_range": "< P3"}], "methodology": "百分位数法 (Percentile Method)", "rule_description": "将100个同年龄、同性别的正常儿童按头围由小到大排列，划分出5个等级区间用于评估个体的大脑及颅骨发育水平。"}, "standard_metadata": {"unit": "厘米 (cm)", "measurement_rule": "头围测量：使用软尺经过眉间点及后脑勺（枕骨粗隆）最高点绕头一周，读数精确到 0.1 cm。适用于 0～3岁儿童。", "standard_version": ["中华人民共和国卫生行业标准《7岁以下儿童生长标准》(WS/T 423—2022)"]}, "head_circumference_percentile_data": {"male_boys": {"unit": "厘米 (cm)", "description": "0～3岁男童年龄别头围百分位数值（源自标准文本表A.11）", "monthly_records": [{"P3": 31.9, "P10": 32.7, "P25": 33.4, "P50": 34.3, "P75": 35.2, "P90": 36.0, "P97": 36.8, "display": "0月(出生)", "age_months": 0}, {"P3": 34.8, "P10": 35.5, "P25": 36.2, "P50": 37.0, "P75": 37.8, "P90": 38.5, "P97": 39.2, "display": "1月", "age_months": 1}, {"P3": 36.9, "P10": 37.6, "P25": 38.3, "P50": 39.1, "P75": 39.9, "P90": 40.6, "P97": 41.3, "display": "2月", "age_months": 2}, {"P3": 38.3, "P10": 39.0, "P25": 39.7, "P50": 40.5, "P75": 41.3, "P90": 42.0, "P97": 42.7, "display": "3月", "age_months": 3}, {"P3": 39.4, "P10": 40.1, "P25": 40.8, "P50": 41.6, "P75": 42.4, "P90": 43.1, "P97": 43.9, "display": "4月", "age_months": 4}, {"P3": 40.3, "P10": 41.0, "P25": 41.7, "P50": 42.5, "P75": 43.4, "P90"