INSERT INTO sys_config (code, sub_code, config, json_config, order_number, enabled, remarks, gmt_created, gmt_modified, gmt_deleted, is_deleted) VALUES ('bmi_eval', 'bmi_eval', null, '{"evaluation_rules": {"indicators": [{"grade": "上等 (肥胖)", "clinical_meaning": "达到儿童肥胖筛查标准。建议调整饮食结构，增加运动量，必要时前往儿童保健科或内分泌科就诊。", "percentile_range": ">= P97"}, {"grade": "中上等 (超重风险)", "clinical_meaning": "体重偏高，存在超重风险。建议关注饮食结构，避免高糖高脂食物，增加日常活动量。", "percentile_range": "P75 <= BMI < P97"}, {"grade": "中等 (正常)", "clinical_meaning": "最健康的理想范围，营养状态与体格发育均衡。", "percentile_range": "P25 <= BMI < P75"}, {"grade": "中下等 (偏瘦)", "clinical_meaning": "体型偏瘦。建议关注日常饮食摄入是否充足，排查是否有偏食或营养吸收不良。", "percentile_range": "P3 <= BMI < P25"}, {"grade": "下等 (消瘦)", "clinical_meaning": "达到儿童消瘦/营养不良筛查标准，建议前往儿童保健科就医排查原因。", "percentile_range": "< P3"}], "methodology": "百分位数法 (Percentile Method)", "rule_description": "将100个同年龄、同性别的正常儿童按 BMI 由低到高排列，划分出5个等级区间用于评估个体的胖瘦程度。"}, "standard_metadata": {"unit": "千克每平方米 (kg/m²)", "measurement_rule": "BMI计算公式：体重(kg) / 身高(m)²。注：2岁以下适用于以体重和身长计算的 BMI，2～7岁以下适用于以体重和身高计算的 BMI。年龄为整月或整岁。", "standard_version": ["中华人民共和国卫生行业标准《7岁以下儿童生长标准》(WS/T 423—2022)"]}, "bmi_percentile_data": {"male_boys": {"unit": "千克每平方米 (kg/m²)", "description": "7岁以下男童年龄别BMI百分位数值（源自标准文本表A.9）", "monthly_records": [{"P3": 11.2, "P10": 11.8, "P25": 12.5, "P50": 13.2, "P75": 14.0, "P90": 14.8, "P97": 15.5, "display": "0月(出生)", "age_months": 0}, {"P3": 13.0, "P10": 13.6, "P25": 14.3, "P50": 15.1, "P75": 16.0, "P90": 16.8, "P97": 17.6, "display": "1月", "age_months": 1}, {"P3": 14.3, "P10": 15.0, "P25": 15.8, "P50": 16.7, "P75": 17.6, "P90": 18.5, "P97": 19.5, "display": "2月", "age_months": 2}, {"P3": 14.9, "P10": 15.7, "P25": 16.5, "P50": 17.4, "P75": 18.5, "P90": 19.5, "P97": 20.5, "display": "3月", "age_months": 3}, {"P3": 15.2, "P10": 16.0, "P25": 16.8, "P50": 17.8, "P75": 18.8, "P90": 19.9, "P97": 21.0, "display": "4月", "age_months": 4}, {"P3": 15.3, "P10": 16.1, "P25": 16.9, "P50": 17.9, "P75": 19.0, "P90": 20.0, "P97": 21.1, "d